CREATE FUNCTION harga_pajak(h integer) RETURNS integer
LANGUAGE sql IMMUTABLE AS $$
  SELECT ROUND(h * 1.11)::integer
$$;

SELECT nama, harga, harga_pajak(harga) FROM produk;

CREATE PROCEDURE tambah_stok(p_id integer, p_jumlah integer)
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE produk SET stok = stok + p_jumlah WHERE id = p_id;
END;
$$;

CALL tambah_stok(7, 30);

CREATE VIEW v_harga_pajak AS
