WITH RECURSIVE cicilan(bulan, sisa) AS (
  SELECT 1, 500000
  UNION ALL
  SELECT bulan + 1, sisa - 100000 FROM cicilan WHERE bulan < 6
)
SELECT * FROM cicilan;

SELECT nama, gaji,
  LAG(gaji) OVER (ORDER BY gaji DESC) - gaji AS selisih_dengan_atas
FROM karyawan;

WITH jual AS (
  SELECT pr.nama, SUM(d.jumlah) AS unit
  FROM detail_pesanan d JOIN produk pr ON pr.id = d.produk_id
  GROUP BY pr.id, pr.nama
)
SELECT * FROM (
  SELECT nama, unit, RANK() OVER (ORDER BY unit DESC) AS peringkat FROM jual
) AS t
WHERE peringkat <= 3
ORDER BY peringkat;

SELECT kategori, nama, harga FROM (
  SELECT kategori, nama, harga,
    ROW_NUMBER() OVER (PARTITION BY kategori ORDER BY harga DESC) AS urut
  FROM produk
) AS t
WHERE urut = 2;
